# warmup, or when remaining budget suggests the final answer should start soon,
# switch into answer-seeking mode and repeatedly nudge toward a natural left
# delimiter until one is emitted. Once inside a verified span, continue with
# grammar-valid constrained decoding; when the constrained suffix is complete,
# allow either another valid token or a natural right delimiter. If a right
# delimiter is emitted by AppendConstrainedOrRightDelimiterStep, immediately
# increment a real closed-span counter. For GSM, prefer one delayed final span,
# so terminate after the first closed span.
# CSD_RATIONALE_END
closed_spans = 0
answer_phase = False
freeform_steps = 0

# invariant helpers.lm == lm
# invariant helpers.parser == parser
# invariant lm.ValidTokensIdsLogits()
# invariant 0 <= stepsLeft <= maxSteps
# invariant |generated| + stepsLeft <= maxSteps
# decreases stepsLeft
while stepsLeft > 0:
    if closed_spans >= 1:
        break
    elif helpers.EndsWithLeftDelimiter(generated):
        if not helpers.CanConstrain(generated):
            break
        elif helpers.IsComplete(generated):
            stepsLeft = helpers.AppendConstrainedOrRightDelimiterStep(prompt, generated, stepsLeft)
            if helpers.EndsWithRightDelimiter(generated):
                closed_spans = closed_spans + 1
        else:
            if helpers.ValidContinuationCount(generated) <= 0:
                break
            elif not helpers.HasBudget(stepsLeft, helpers.MinStepsToComplete(generated)):
                break
            else:
                stepsLeft = helpers.AppendConstrainedStep(prompt, generated, stepsLeft)
    elif answer_phase:
        stepsLeft = helpers.AppendUnconstrainedNudgeLeftDelimiterStep(prompt, generated, stepsLeft)
    else:
        if freeform_steps >= 4:
            answer_phase = True
            stepsLeft = helpers.AppendUnconstrainedNudgeLeftDelimiterStep(prompt, generated, stepsLeft)
        elif not helpers.HasBudget(stepsLeft, 1 + helpers.ParserDistanceToComplete(generated)):
            answer_phase = True
            stepsLeft = helpers.AppendUnconstrainedNudgeLeftDelimiterStep(prompt, generated, stepsLeft)
        else:
            stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
            freeform_steps = freeform_steps + 1

